param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Polygon([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
function Rectangle([double]$row,[double]$column,[double]$phi,[double]$length1,[double]$length2){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenRectangle2ContourXld([ref]$x,[HalconDotNet.HTuple]$row,[HalconDotNet.HTuple]$column,[HalconDotNet.HTuple]$phi,[HalconDotNet.HTuple]$length1,[HalconDotNet.HTuple]$length2);$x}
function Concat($objects){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($one in $objects){[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{if($null-ne$combined){$combined.Dispose()}}};Write-Output -NoEnumerate $all}

$temp=Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s51-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}

# A: high-frequency commands are permanent; project, batch, debug and image sub-tasks are progressive disclosure.
$developer=Field 'DeveloperToolbarPanel';foreach($name in @('SaveRecipeButton','OpenImageButton','RunOnceButton','StopRunButton','EnterProductionModeButton')){Assert ([object]::ReferenceEquals((Field $name).Parent,$developer)) "$name is not a permanent top command"}
$developerMore=Field 'DeveloperMoreToggleButton';$developerMorePanel=(Field 'NewRecipeButton').Parent;Assert ($developerMore.IsChecked-ne$true) 'Developer more panel should be collapsed by default';foreach($name in @('NewRecipeButton','LoadRecipeButton','SaveRecipeAsButton','OpenFolderButton')){Assert ([object]::ReferenceEquals((Field $name).Parent,$developerMorePanel)) "$name did not move into More"}
$imageLeft=(Field 'ImageSelectButton').Parent;foreach($name in @('ImageSelectButton','ImagePanButton','ImageFitButton')){Assert ([object]::ReferenceEquals((Field $name).Parent,$imageLeft)) "$name is not a permanent image command"}
$imageTask=Field 'ImageTaskToggleButton';$imageTaskPanel=(Field 'ImageWorkspaceExpandButton').Parent;Assert ($imageTask.IsChecked-ne$true-and(Field 'RoiToolsToggleButton').IsChecked-ne$true-and(Field 'ImageMoreToggleButton').IsChecked-ne$true) 'Image tasks should be collapsed by default';foreach($name in @('ImageWorkspaceExpandButton','ImageLayoutToggleButton','ImageOneToOneButton','RoiToolsToggleButton','ImageMoreToggleButton')){Assert ([object]::ReferenceEquals((Field $name).Parent,$imageTaskPanel)) "$name did not move into image task entry"}

# B: smallest_rectangle2_xld measurement, direction normalization, range selection, ownership and downstream chain.
$kind=[Enum]::Parse($kindType,'XldMinimumRectangleDirectionMeasurement');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($kind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($kind));Assert(($inputs|Where-Object PortName -eq XLD).Count-eq1-and($outputs|Where-Object PortName -eq Area).DataType-eq'Number'-and($outputs|Where-Object PortName -eq XLD).DataType-eq'XLD') 'Typed minimum rectangle ports missing'
$rect=Rectangle 100 120 0.4 40 15;$rectReverse=Rectangle 100 120 (-[Math]::PI+0.4) 40 15;$open=Polygon ([double[]]@(0,0,20,20)) ([double[]]@(0,30,30,0));$bowtie=Polygon ([double[]]@(0,20,0,20,0)) ([double[]]@(0,20,20,0,0));$degenerate=Polygon ([double[]]@(10,10,10)) ([double[]]@(10,10,10));$input=Concat @($rect,$rectReverse,$open,$bowtie,$degenerate);foreach($x in @($rect,$rectReverse,$open,$bowtie,$degenerate)){$x.Dispose()}
$measure=Tool XldMinimumRectangleDirectionMeasurement 'S51 Minimum Rectangle';$run=$mainType.GetMethod('RunXldMinimumRectangleDirectionMeasurementTool',$private);function RunMeasure($x){try{$run.Invoke($window,[object[]]@($measure,$x.PSObject.BaseObject))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
try{$measure.Parameters.XldMinimumRectangleContourMode='All';$measure.Parameters.XldMinimumRectangleMinimumPointCount=2;$measure.Parameters.XldMinimumRectangleClosureTolerance=0;$measure.Parameters.XldMinimumRectangleWidthMinimum=0;$measure.Parameters.XldMinimumRectangleWidthMaximum=1000;$measure.Parameters.XldMinimumRectangleHeightMinimum=0;$measure.Parameters.XldMinimumRectangleHeightMaximum=1000;$result=RunMeasure $input;Assert($result.ResultCode-eq'OK'-and[int](Out $measure MeasuredCount)-eq4-and[int](Out $measure ContourCount)-eq4) 'All-contour measurement failed';Assert([int](Out $measure OpenCount)-eq1-and[int](Out $measure ClosedCount)-eq4-and[int](Out $measure SelfIntersectingCount)-eq1-and[int](Out $measure DegenerateCount)-eq1) 'Open/closed/self-intersect/degenerate counters failed';Assert([Math]::Abs([double](Out $measure Width)-80)-lt.05-and[Math]::Abs([double](Out $measure Height)-30)-lt.05-and[Math]::Abs([double](Out $measure Area)-2400)-lt1) 'Minimum rectangle dimensions are incorrect';Assert([Math]::Abs([Math]::Sin([double](Out $measure Phi)-0.4))-lt.001) 'Half-turn direction normalization is incorrect';[HalconDotNet.HObject]$copy=(Out $measure XLD).CreateXldCopy();try{[HalconDotNet.HTuple]$overlayCount=$null;[HalconDotNet.HOperatorSet]::CountObj($copy,[ref]$overlayCount);Assert($overlayCount.I-eq4) 'Rectangle overlay object count is incorrect'}finally{$copy.Dispose()};$old=Out $measure XLD;$measure.Parameters.XldMinimumRectangleContourMode='ClosedOnly';RunMeasure $input|Out-Null;Assert([int](Out $measure ContourCount)-eq3-and$old.IsDisposed) 'Closed-only policy or old snapshot release failed';$measure.Parameters.XldMinimumRectangleContourMode='All';$measure.Parameters.XldMinimumRectangleWidthMinimum=79.9;$measure.Parameters.XldMinimumRectangleWidthMaximum=80.1;$measure.Parameters.XldMinimumRectangleHeightMinimum=29.9;$measure.Parameters.XldMinimumRectangleHeightMaximum=30.1;RunMeasure $input|Out-Null;Assert([int](Out $measure ContourCount)-eq2-and(Out $measure OriginalIndices)-eq'[1,2]') 'Inclusive major/minor range selection failed';[HalconDotNet.HTuple]$sourceCount=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$sourceCount);Assert($sourceCount.I-eq5) 'Upstream XLD ownership changed'}finally{$input.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$measure.Parameters.XldMinimumRectangleWidthMinimum=0;$measure.Parameters.XldMinimumRectangleWidthMaximum=1000;$measure.Parameters.XldMinimumRectangleHeightMinimum=0;$measure.Parameters.XldMinimumRectangleHeightMaximum=1000;$emptyResult=RunMeasure $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $measure ContourCount)-eq0) 'Empty input semantics failed'}finally{$empty.Dispose()}
$measure.Parameters.XldMinimumRectangleMinimumPointCount=1;Assert(-not[string]::IsNullOrWhiteSpace($measure.Parameters.Validate($kind))) 'Invalid minimum point count accepted';$measure.Parameters.XldMinimumRectangleMinimumPointCount=2;$measure.Parameters.XldMinimumRectangleWidthMinimum=10;$measure.Parameters.XldMinimumRectangleWidthMaximum=5;Assert(-not[string]::IsNullOrWhiteSpace($measure.Parameters.Validate($kind))) 'Invalid width range accepted';$measure.Parameters.XldMinimumRectangleWidthMinimum=0;$measure.Parameters.XldMinimumRectangleWidthMaximum=1000
$flow=Field 'flowTools';$producer=Tool XldPointClosureFilter 'S51 Rectangle Source';$chain=Tool XldMinimumRectangleDirectionMeasurement 'S51 Rectangle Measure';$judge=Tool NumericJudge 'S51 Area Judge';$chain.SetInputBinding('XLD',$producer.ToolId,'XLD');$judge.SetInputBinding('Value',$chain.ToolId,'Area');$judge.InputToolId=$chain.ToolId;$judge.InputPortName='Area';$judge.NumericLowerLimit=2399;$judge.NumericUpperLimit=2401;$flow.Add($producer);$flow.Add($chain);$flow.Add($judge);$source=Rectangle 200 220 0.4 40 15;try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($source.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$source.Dispose()};$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$execute.Invoke($window,[object[]]@($chain,'S51 chain'))|Out-Null;$execute.Invoke($window,[object[]]@($judge,'S51 chain'))|Out-Null;Assert($chain.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Real XLD/Number downstream chain failed'
(Field 'FlowToolList').SelectedItem=$measure;$measure.Parameters.XldMinimumRectangleContourMode='OpenOnly';$measure.Parameters.XldMinimumRectangleMinimumPointCount=5;$measure.Parameters.XldMinimumRectangleClosureTolerance=2;$measure.Parameters.XldMinimumRectangleWidthMinimum=12;$measure.Parameters.XldMinimumRectangleWidthMaximum=90;$measure.Parameters.XldMinimumRectangleHeightMinimum=6;$measure.Parameters.XldMinimumRectangleHeightMaximum=40;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($measure))|Out-Null;Assert((Field 'DockXldMinimumRectangleDirectionPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldMinimumRectangleMinimumPointCountTextBox').Text-eq'5') 'Dock configuration synchronization failed';$flow.Add($measure);$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$measure.ToolId}|Select-Object -First 1;Assert($saved.Parameters.XldMinimumRectangleContourMode-eq'OpenOnly'-and$saved.Parameters.XldMinimumRectangleWidthMinimum-eq12-and$saved.Parameters.XldMinimumRectangleHeightMaximum-eq40) 'Recipe persistence failed'
$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S51 command hierarchy and HALCON XLD minimum-rectangle/direction smoke tests passed; BSB not implemented by user directive.'
